package org.marketreview.nativeapp;
import org.json.*;
import java.util.*;
import static org.marketreview.nativeapp.WatchlistWorkspaceModel.*;

public final class WatchlistHostAdapter {
 private static JSONObject issue(String reason,boolean blocking,Object original)throws Exception{return object("state","unverified","reason",reason,"blocking",blocking,"original",original==null?JSONObject.NULL:original);}
 public static JSONObject inputs(JSONArray current,JSONObject evidence)throws Exception{JSONArray primary=new JSONArray(),main=new JSONArray(),legacy=new JSONArray(),issues=new JSONArray();boolean allowed=true;for(int i=0;i<current.length();i++){Object value=current.get(i);if(!(value instanceof JSONObject)){issues.put(issue("当前目录记录不是完整对象",true,value));allowed=false;continue;}JSONObject row=(JSONObject)value;if(row.has("transient")&&!(row.opt("transient") instanceof Boolean)){issues.put(issue("临时观察标记不是明确布尔值，未猜主自选身份",true,row.opt("id")));allowed=false;}if(Boolean.TRUE.equals(row.opt("transient")))continue;primary.put(row);main.put(row.opt("id"));}JSONObject in=object("instruments",primary,"mainIds",main);try{WatchlistWorkspaceStore.inputSnapshot(in,"host-input",new JSONArray());}catch(Exception e){issues.put(issue(e.getMessage(),true,null));allowed=false;}
  if(Boolean.TRUE.equals(evidence.opt("nativeLocalSingletonContract"))){Map<String,Integer>at=new LinkedHashMap<>();JSONObject colors=evidence.optJSONObject("localColors");if(colors==null)colors=new JSONObject();if(evidence.has("localColors")&&!(evidence.opt("localColors") instanceof JSONObject)){issues.put(issue("本机旧识别色映射结构未核验",true,evidence.opt("localColors")));allowed=false;}for(int i=0;i<primary.length();i++){JSONObject row=primary.getJSONObject(i);if(!(row.opt("group") instanceof String)||row.getString("group").isEmpty()){issues.put(issue("本机单组标签缺失，未凭名称或代码另造归属",true,row.opt("id")));allowed=false;continue;}String name=row.getString("group");if(!at.containsKey(name)){at.put(name,legacy.length());legacy.put(object("name",name,"color",colors.has(name)?colors.get(name):"","readOnly",false,"memberIds",new JSONArray(),"sourceMeta",object("projection","owned-native-single-group/v1","field","group","nativeLegacyLabel",name)));}legacy.getJSONObject(at.get(name)).getJSONArray("memberIds").put(row.get("id"));}}else{issues.put(issue("未提供原生本机单组字段的明确合同，旧标签保持未核验",true,null));allowed=false;}
  if(!evidence.has("importedGroups"))issues.put(issue("当前原生目录没有源只读组身份/来源/颜色；未推断外部导入组，须由宿主提供明确元数据",false,null));else if(!(evidence.opt("importedGroups") instanceof JSONArray)){issues.put(issue("导入只读组视图未核验",true,evidence.opt("importedGroups")));allowed=false;}else{JSONArray imported=evidence.getJSONArray("importedGroups");for(int i=0;i<imported.length();i++){Object value=imported.get(i);legacy.put(value);JSONObject g=value instanceof JSONObject?(JSONObject)value:new JSONObject();List<String>missing=new ArrayList<>();for(String k:new String[]{"groupId","sourceId","name","color"})if(!(g.opt(k) instanceof String)||(!k.equals("color")&&g.getString(k).trim().isEmpty()))missing.add(k);if(!Boolean.TRUE.equals(g.opt("readOnly")))missing.add("readOnly=true");if(!(g.opt("memberIds") instanceof JSONArray))missing.add("memberIds");if(!(value instanceof JSONObject)||!missing.isEmpty()){issues.put(issue("导入只读组缺明确字段："+String.join(",",missing),true,value));allowed=false;}}}
  in.put("legacyGroups",legacy);try{WatchlistWorkspaceStore.project(in);}catch(Exception e){issues.put(issue("首次旧组投影未核验："+e.getMessage(),true,legacy));allowed=false;}if(!allowed)in.remove("legacyGroups");return object("schema","watchlist-host-adapter/v1","inputs",in,"canInitialize",allowed,"legacyGroupCandidates",legacy,"issues",issues);}
 public static JSONObject requireInputs(JSONObject capture)throws Exception{need(text(capture,"schema").equals("watchlist-host-adapter/v1")&&Boolean.TRUE.equals(capture.opt("canInitialize")),"首次本地组投影存在未核验原因，未部分初始化");return capture.getJSONObject("inputs");}
 public static JSONObject initializationPreview(JSONObject captured)throws Exception{JSONObject in=requireInputs(captured),out=object("schema","watchlist-host-initialization-preview/v1","rosterScope",WatchlistReconciliationModel.scope(in),"legacyGroups",in.get("legacyGroups"),"issues",captured.get("issues"));out.put("fingerprint",hash(out));return out;}
 public static void verifyInitialization(JSONObject packet,JSONObject result)throws Exception{need(text(packet,"schema").equals("watchlist-host-initialization-preview/v1")&&text(result,"state").equals("ready"),"初始投影回执未确认");JSONObject scopeCopy=copy(packet);String fingerprint=text(scopeCopy,"fingerprint");scopeCopy.remove("fingerprint");need(hash(scopeCopy).equals(fingerprint),"初始化预览摘要失效");JSONObject s=validate(result.getJSONObject("snapshot"));need(equal(WatchlistReconciliationModel.scope(object("instruments",s.get("instruments"),"mainIds",s.get("mainIds"))),packet.get("rosterScope")),"初始投影主自选身份已变");JSONArray expected=packet.getJSONArray("legacyGroups"),actual=s.getJSONArray("groups");need(expected.length()==actual.length(),"已有侧库投影与本次预览分组数量不同");for(int i=0;i<actual.length();i++){JSONObject g=copy(actual.getJSONObject(i)),wanted=expected.getJSONObject(i);if(!wanted.has("groupId")){need(text(g,"groupId").matches("local:[0-9a-f-]{36}"),"本地组持久随机ID未确认");g.remove("groupId");}need(equal(g,wanted),"初始完整分组/来源/颜色回执不同，请重读已有侧库");}}
 public static JSONObject directory(JSONObject result,String requested)throws Exception{need(text(result,"schema").equals("watchlist-workspace-store-result/v1"),"分组侧库结果格式无效");String state=text(result,"state");need(state.equals("ready")||state.equals("needsReconciliation")||state.equals("uninitialized"),"分组侧库状态不支持");JSONObject c=new JSONObject();if(state.equals("ready"))c=WatchlistWorkspaceStore.config(validate(result.getJSONObject("snapshot")));else if(state.equals("needsReconciliation"))c=WatchlistWorkspaceStore.validateConfig(result.getJSONObject("config"));JSONArray groups=c.optJSONArray("groups");if(groups==null)groups=new JSONArray();Map<String,Integer>counts=new HashMap<>();for(int i=0;i<groups.length();i++){String name=text(groups.getJSONObject(i),"name");counts.put(name,counts.getOrDefault(name,0)+1);}JSONArray options=new JSONArray().put(object("groupId","","name","全部自选","displayName","全部自选","color","","readOnly",true,"memberIds",new JSONArray()));String selected="",selectedName="全部自选";JSONArray members=new JSONArray();for(int i=0;i<groups.length();i++){JSONObject g=copy(groups.getJSONObject(i));String name=text(g,"name"),id=text(g,"groupId");g.put("displayName",counts.get(name)>1?name+" · "+id:name).put("memberCount",g.getJSONArray("memberIds").length());options.put(g);if(id.equals(requested)){selected=id;selectedName=name;members=g.getJSONArray("memberIds");}}return object("schema","watchlist-host-directory/v1","state",state,"options",options,"selectedGroupId",selected,"selectedName",selectedName,"memberIds",members,"requiresReconciliation",state.equals("needsReconciliation"));}
 public static boolean includes(JSONObject directory,String id)throws Exception{need(text(directory,"schema").equals("watchlist-host-directory/v1")&&fullId(id),"目录或完整证券身份无效");if(text(directory,"selectedGroupId").isEmpty())return true;JSONArray members=directory.getJSONArray("memberIds");for(int i=0;i<members.length();i++)if(id.equals(members.getString(i)))return true;return false;}
 public static String diagnostics(JSONObject capture)throws Exception{List<String>out=new ArrayList<>();JSONArray issues=capture.getJSONArray("issues");for(int i=0;i<issues.length();i++)out.add(issues.getJSONObject(i).getString("reason"));return String.join("\n",out);}
}
